"""Builds the chatbot's reply from fixed templates. No text is generated by AI, so every
possible reply can be read and checked in advance: warm, short, non-judgemental, no medical advice.
"""
import random

# 2-3 variants per mood, chosen at random so the bot doesn't sound repetitive
REPLIES = {
    "sadness": [
        "I'm sorry you're feeling this way. It's okay to feel sad, and thank you for telling me.",
        "That sounds really heavy. You don't have to carry it alone. Would you like to tell me more?",
        "I hear you. Feeling low is hard. Be gentle with yourself today.",
    ],
    "fear": [
        "That sounds worrying. It's understandable to feel anxious about it.",
        "Feeling scared or anxious is really uncomfortable. Let's take it one small step at a time.",
        "Thank you for sharing that. A few slow breaths can sometimes help when worry feels big.",
    ],
    "anger": [
        "It sounds like something really upset you. Your feelings make sense.",
        "That sounds frustrating. It's okay to feel angry; taking a short pause can help before you respond.",
    ],
    "disgust": [
        "That sounds really unpleasant to deal with. It's okay to feel put off by it.",
        "I'm sorry you had to go through that. Do you want to talk about what happened?",
    ],
    "joy": [
        "That's lovely to hear! What made it a good moment for you?",
        "I'm really glad you're feeling good. Hold on to that feeling!",
    ],
    "surprise": [
        "That sounds unexpected! How are you feeling about it?",
        "Wow, that's a surprise. Do you want to talk it through?",
    ],
    # Used when the emotion is "neutral": the sentiment decides the tone instead
    "neutral_negative": [
        "It sounds like things are a bit tough right now. I'm here to listen.",
        "Thanks for sharing. Would you like to talk more about what's on your mind?",
    ],
    "neutral_positive": [
        "Sounds like things are going okay. Anything you'd like to talk about?",
        "Good to hear from you. How has the rest of your day been?",
    ],
    "neutral": [
        "Thanks for sharing. How are you feeling about it?",
        "I'm here to listen. Tell me more whenever you're ready.",
        "Okay, I'm listening. What's on your mind today?",
    ],
}

# Resource tags (see app/schemas/resource.py) suggested for each mood. Empty = no suggestion.
RESOURCE_TAGS = {
    "sadness": ["sadness", "low_mood", "loneliness"],
    "fear": ["anxiety", "fear"],
    "anger": ["anger"],
    "disgust": ["stress"],
    "joy": [],
    "surprise": [],
    "neutral_negative": ["stress", "low_mood"],
    "neutral_positive": [],
    "neutral": [],
}

DISCLAIMER = (
    "I'm an automated support assistant, not a therapist or doctor, and I can't diagnose anything. "
    "If you are in danger, call 112 or Tele-MANAS on 14416."
)


def mood_key(emotion: str, sentiment: str) -> str:
    """The emotion decides the reply; for a 'neutral' emotion, the sentiment does."""
    if emotion == "neutral":
        return {"negative": "neutral_negative", "positive": "neutral_positive"}.get(sentiment, "neutral")
    return emotion if emotion in REPLIES else "neutral"


def build_reply(emotion: str, sentiment: str) -> tuple[str, list[str]]:
    """Returns (reply text, resource tags to suggest)."""
    key = mood_key(emotion, sentiment)
    return random.choice(REPLIES[key]), RESOURCE_TAGS[key]
